{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law","requirement":"A landlord may not require a security deposit above one and one-half times one month's rent, and annual deposit increases may not exceed 10%. The deposit plus interest, less itemized deductions, must be returned within 30 days after the tenancy ends.","key_value":"1.5 months' rent max deposit; 10% annual deposit increase cap","coverage_conditions":"Security deposits for residential tenancies in New Jersey. Does not apply to seasonal use or rental of not more than 125 consecutive days by a person with a permanent residence elsewhere.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Residential rentals; seasonal use or rental exempt"},"exemptions":"Security deposits for seasonal use or rental of not more than 125 consecutive days by a person whose permanent residence is elsewhere; does not mean living quarters for seasonal, temporary or migrant farm workers.","penalty":"Tenant may sue for double the amount wrongfully withheld, plus court costs and reasonable attorney's fees.","effective_date":null,"citation":"N.J.S.A. 46:8-21.2","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month's rent ( N.J.S.A. 46:8-21.2 ). It can be less. Any additional yearly security deposit increase may not exceed 10% of the current security deposit.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic-violence lease termination","requirement":"When a tenant terminates a lease under the Safe Housing Act because of domestic violence, the landlord must make the security deposit plus interest available for return within 15 business days after the lease is terminated.","key_value":"15 business days","coverage_conditions":"Tenant terminations of a lease under the Safe Housing Act (domestic violence); the law does not apply to transient or seasonal rentals.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Safe Housing Act domestic-violence lease terminations"},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant's security deposit, plus any interest earned, to the tenant or the tenant's agent.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
